WITH FilteredAccounts AS (SELECT * FROM accounts WHERE customer_id IS NOT NULL), status_summary AS (SELECT status, CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 26000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(CASE WHEN status = 'FROZEN' THEN 1 ELSE 0 END) AS frozen_count FROM FilteredAccounts GROUP BY status, CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 26000 THEN 'mid' ELSE 'low' END) SELECT status, balance_bucket, frozen_count FROM status_summary WHERE frozen_count >= 48 ORDER BY 3 DESC, status DESC;
